(() => {
  const {$,esc,image,read,write,toast}=Atlas;const all=window.ATLAS_CATALOG.cards,unique=new Map(),lookup=new Map();all.forEach(c=>{lookup.set(c.uid,c);if(!unique.has(c.id)||c.uid===c.id)unique.set(c.id,c);});unique.forEach((c,id)=>lookup.set(id,c));
  const routes={play:['Uma base pronta para aprender.','Um Starter Deck oferece uma lista montada para você conhecer as interações. Confira o conteúdo da edição: o nome do produto e o idioma importam. Depois, use o construtor para planejar alterações sem trocar cartas ao acaso.','Confira se o produto contém os componentes necessários, se o idioma é adequado ao seu evento e se a lista segue o formato que você pretende jogar.'],card:['Procure o ID antes de procurar o preço.','Cartas avulsas permitem procurar uma peça específica. Pesquise o ID exato e compare arte, idioma, condição e versão. As várias artes do mesmo ID normalmente contam juntas no limite de cópias do deck.','Um booster é um produto de conteúdo variável. A presença de uma carta na coleção não garante que ela venha em cada pacote.'],collect:['Escolha o que faz sentido para a sua coleção.','Você pode organizar uma coleção por personagem, grupo, produto ou arte. Definir o objetivo ajuda a distinguir uma carta que você quer de uma versão parecida. Use os filtros de personagens e grupos para criar sua seleção.','Abrir produto selado e comprar uma arte específica são experiências diferentes. Verifique as informações da edição e a descrição da oferta.'],promo:['A distribuição faz parte da identidade.','Promos podem estar associadas a eventos, campanhas, produtos especiais ou premiações. Consulte a ficha da impressão e a página de origem antes de supor que uma carta sai em um booster comum.','Uma carta com o mesmo ID pode ter várias distribuições. O catálogo informa a origem registrada; a organização do evento ou o vendedor informa a disponibilidade atual.']};
  const buttons=[...document.querySelectorAll('[data-route]')];function selectRoute(button){const values=routes[button.dataset.route];buttons.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});$('#route-detail').setAttribute('aria-labelledby',button.id);$('#route-detail').innerHTML=`<span class="route-compass">✧</span><div><h3>${values[0]}</h3><p>${values[1]}</p><small>${values[2]}</small></div>`;}
  buttons.forEach((button,i)=>{button.onclick=()=>selectRoute(button);button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const target=buttons[(i+(e.key==='ArrowRight'?1:buttons.length-1))%buttons.length];selectRoute(target);target.focus();};});selectRoute(buttons[0]);
  async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado para a área de transferência.');}catch{const box=document.createElement('textarea');box.value=text;box.setAttribute('aria-label','Texto para copiar');document.body.append(box);box.select();const copied=document.execCommand?.('copy');box.remove();toast(copied?'Copiado.':'Não foi possível copiar automaticamente. Selecione os códigos na lista.');}}
  function showCard(c){$('#buy-card-result').hidden=false;$('#buy-card-result').innerHTML=`<img src="${esc(image(c))}" alt="${esc(c.name)}"><div><span class="eyebrow gold">${esc(c.id)} · ${esc(c.uid)}</span><h3>${esc(c.name)}</h3>${c.spoiler?'<p class="preview-notice">Prévia: confira o lançamento e se a oferta é uma pré-venda.</p>':''}<p>Produtos / grupos registrados para esta impressão:</p><ul>${c.sets.map(s=>`<li><a href="home.html?set=${encodeURIComponent(s.id)}&prints=1">${esc(s.name)} ↗</a></li>`).join('')}</ul><div class="quiz-actions"><button class="btn-outline" id="copy-card-code">Copiar ID</button><a class="btn-gold" href="carta.html?id=${encodeURIComponent(c.uid)}">Ver a impressão ↗</a></div><a class="buy-origin" href="${esc(c.source)}" target="_blank" rel="noopener">Conferir distribuição e registro na fonte ↗</a></div>`;$('#copy-card-code').onclick=()=>copy(c.id+' — '+c.name+' ('+c.uid+')');}
  function search(){const q=AtlasTaxonomy.canonical($('#buy-card-search').value.trim());if(!q){$('#buy-search-results').textContent='Digite um nome ou ID para consultar.';return;}const rows=[...unique.values()].filter(c=>AtlasTaxonomy.canonical(c.id+' '+c.name).includes(q));$('#buy-search-results').innerHTML=rows.length?rows.slice(0,12).map(c=>`<button data-buy-card="${esc(c.uid)}"><b>${esc(c.name)}</b><span>${esc(c.id)}</span></button>`).join(''):'<p>Nenhuma carta encontrada nessa fotografia do catálogo.</p>';if(rows.length===1)showCard(rows[0]);}
  $('#buy-search-button').onclick=search;$('#buy-card-search').onkeydown=e=>{if(e.key==='Enter')search();};$('#buy-search-results').onclick=e=>{const b=e.target.closest('[data-buy-card]');if(b)showCard(lookup.get(b.dataset.buyCard));};const query=new URLSearchParams(location.search).get('id');if(query&&lookup.has(query)){const c=lookup.get(query);$('#buy-card-search').value=c.id;showCard(c);}
  const sellers=[{name:'MYP Cards',region:'br',kind:'Marketplace',text:'Categoria de One Piece com cartas avulsas, selados e outros produtos. Compare as condições de cada vendedor.',url:'https://mypcards.com/onepiece'},{name:'Universo Cards',region:'br',kind:'Loja · cartas avulsas',text:'Página dedicada a cartas avulsas de One Piece. Confira ID, versão e condição da oferta.',url:'https://universocards.com.br/collections/one-piece-singles'},{name:'Collecta TCG',region:'br',kind:'Loja · singles e selados',text:'Loja com categoria de One Piece e opções de produtos de TCG. Consulte atendimento e envio no site.',url:'https://www.collectatcg.com.br/'},{name:'Arena CWG',region:'br',kind:'Loja · produtos de One Piece',text:'Categoria de One Piece com produtos selados. Verifique o conteúdo de cada edição antes de escolher.',url:'https://www.arenacwg.com/onepiece'},{name:'TCGplayer',region:'global',kind:'Marketplace internacional',text:'Categoria internacional de One Piece. Confira países atendidos, idioma, frete e custo final no serviço.',url:'https://www.tcgplayer.com/categories/trading-and-collectible-card-games/one-piece-card-game'}];
  function renderSellers(){const region=$('#seller-region').value;$('#seller-grid').innerHTML=sellers.filter(s=>region==='all'||s.region===region).map(s=>`<article><span>${s.kind}</span><h3>${s.name}</h3><p>${s.text}</p><a href="${s.url}" target="_blank" rel="noopener">Consultar no site <span>↗</span></a><small>Link consultado em 23/10/2026 · sem preço sincronizado</small></article>`).join('');}$('#seller-region').onchange=renderSellers;renderSellers();
  const saved=read('atlas-saved-decks',[]);const storedDecks=Array.isArray(saved)?saved.filter(r=>r?.data):[];$('#shopping-deck').innerHTML='<option value="draft">Meu rascunho atual</option>'+storedDecks.map(r=>`<option value="${esc(r.id)}">${esc(r.data.name)}</option>`).join('');let shopping=[];const rawOwned=read('atlas-owned',{});const owned=rawOwned&&typeof rawOwned==='object'&&!Array.isArray(rawOwned)?rawOwned:{};
  function currentDeck(){try{const id=$('#shopping-deck').value;if(id==='draft'){const draft=read('atlas-deck-draft',null);return draft?AtlasDeck.parseImport(AtlasDeck.exported(draft),lookup):null;}const row=storedDecks.find(d=>d.id===id);return row?AtlasDeck.parseImport(row.data,lookup):null;}catch{return null;}}
  function renderShopping(){const deck=currentDeck();if(!deck){shopping=[];$('#shopping-summary').textContent='Monte ou carregue um deck para gerar sua lista.';$('#shopping-rows').innerHTML='<div class="shopping-empty"><span>⚑</span><p>Sua lista começa com a escolha de um Líder.</p><a class="btn-gold" href="decks.html">Começar meu deck ↗</a></div>';return;}const entries=[{id:lookup.get(deck.leader).id,card:lookup.get(deck.leader),qty:1},...Object.entries(deck.cards).map(([id,row])=>({id,card:lookup.get(row.uid),qty:row.qty}))];const don=lookup.get(deck.donArt);entries.push({id:don?.id||'_don_generic',card:don||null,qty:10});shopping=entries.map(row=>({...row,have:Math.max(0,Math.min(50,Number(owned[row.id])||0)),need:Math.max(0,row.qty-(Number(owned[row.id])||0))}));const missing=shopping.reduce((n,r)=>n+r.need,0);$('#shopping-summary').textContent=deck.name+' · '+missing+' cartas / recursos restantes nesta lista';const shown=shopping.filter(row=>!$('#missing-only').checked||row.need>0);$('#shopping-rows').innerHTML=shown.length?shown.map(row=>`<div class="shopping-row">${row.card?`<img src="${esc(image(row.card))}" alt="" loading="lazy">`:'<span class="don-list-icon">DON!!</span>'}<div><b>${esc(row.card?.name||'DON!! · arte livre')}</b><small>${row.id==='_don_generic'?'Deck de recursos':esc(row.id)} · precisa de ${row.qty}</small></div><label>Já possuo<input type="number" min="0" max="50" step="1" value="${row.have}" data-owned="${esc(row.id)}" aria-label="Quantidade possuída de ${esc(row.card?.name||'DON!!')}"></label><span class="shopping-need">Faltam <b>${row.need}</b></span>${row.card?`<a href="comprar.html?id=${encodeURIComponent(row.card.uid)}">Consultar ↗</a>`:''}</div>`).join(''):'<p class="complete-collection">✓ Você marcou todas as quantidades desta lista como possuídas.</p>';}
  $('#shopping-rows').onchange=e=>{const field=e.target.closest('[data-owned]');if(!field)return;owned[field.dataset.owned]=Math.max(0,Math.min(50,Math.floor(Number(field.value)||0)));if(!write('atlas-owned',owned))toast('Não foi possível salvar a coleção neste navegador.');renderShopping();};$('#shopping-deck').onchange=renderShopping;$('#missing-only').onchange=renderShopping;$('#copy-shopping').onclick=()=>{if(!shopping.length)return toast('Monte um deck primeiro.');const missing=shopping.filter(r=>r.need>0);copy(missing.length?missing.map(r=>r.need+'x '+(r.card?r.card.id+' '+r.card.name:'DON!! (arte livre)')).join('\n'):'Nenhuma carta faltante na lista.');};renderShopping();
})();
